import { WindowConf, createDefaultWindowConf, createDefaultFloatWindowConf, WindowType } from '@droid/android';
import { toProxy, useTranslation, useProxyWatch } from '@fanfanlo';
import {
  Box,
  Button,
  TextField,
  Typography,
  Alert,
  Stack,
  Chip,
} from '@mui/material';
import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { isTagExists, detectContentType } from './data';

export interface QuickCreateFormProps {
  initialConf?: WindowConf;  // 初始配置（用于编辑模式）
  onQuickCreate: (conf: WindowConf) => void;  // 快速创建完成,返回列表
  onDetailedEdit: (conf: WindowConf) => void; // 详细编辑,切换到编辑模式
  onCancel: () => void;
  hideForegroundText?: boolean;  // 是否隐藏前台服务提示文本
  hideTag?: boolean;  // 是否隐藏 tag 字段
}

/**
 * QuickCreateForm - 快速创建悬浮窗配置表单
 *
 * 必填项:
 * - 窗口标识(tag)
 * - 内容(URL 或 HTML)
 *
 * 推荐项:
 * - 前台服务提示文本
 *
 * 可选项:
 * - 窗口说明
 * - WebView JS 参数(折叠)
 */
export function QuickCreateForm({ initialConf, onQuickCreate, onDetailedEdit, onCancel, hideForegroundText = false, hideTag = false }: QuickCreateFormProps) {
  const { t } = useTranslation('homepage/components/android-float/window/content');
  const router = useRouter();

  console.log('QuickCreateForm: component mounted, initialConf:', initialConf, 'hideForegroundText:', hideForegroundText, 'hideTag:', hideTag);

  // 创建配置对象
  const [conf] = useState(() => {
    if (initialConf) {
      console.log('QuickCreateForm: using initialConf');
      return toProxy(initialConf);
    }
    console.log('QuickCreateForm: creating default conf');
    const defaultConf = createDefaultWindowConf();
    defaultConf.windowType = WindowType.Float;
    defaultConf.floatWindowConf = createDefaultFloatWindowConf();
    return toProxy(defaultConf);
  });

  // UI状态
  const [contentInput, setContentInput] = useState('');
  const [detectedType, setDetectedType] = useState<'url' | 'html' | 'invalid' | null>(null);
  const [errors, setErrors] = useState<Record<string, string>>({});

  // 监听tag变化,实时校验重复
  const [tag] = useProxyWatch(conf, 'tag', conf.tag);

  // 监听前台服务文本变化
  const [foregroundText] = useProxyWatch(
    conf.floatWindowConf,
    'foregroundText',
    conf.floatWindowConf?.foregroundText || ''
  );

  console.log('QuickCreateForm: render, tag:', tag, 'contentInput:', contentInput, 'hideTag:', hideTag);

  /**
   * 当 initialConf 存在时，初始化表单数据
   */
  useEffect(() => {
    console.log('[QuickCreateForm] useEffect - initialConf changed:', initialConf)

    if (initialConf) {
      console.log('[QuickCreateForm] initialConf provided, initializing form with existing data')

      // 更新 conf 的所有属性
      console.log('[QuickCreateForm] updating conf with initialConf properties')
      Object.assign(conf, initialConf)

      // 初始化 contentInput
      if (initialConf.htmlConf?.url) {
        console.log('[QuickCreateForm] setting contentInput from url:', initialConf.htmlConf.url)
        setContentInput(initialConf.htmlConf.url)
      } else if (initialConf.htmlConf?.html) {
        console.log('[QuickCreateForm] setting contentInput from html (length):', initialConf.htmlConf.html.length)
        setContentInput(initialConf.htmlConf.html)
      }
    }
  }, [initialConf, conf])

  /**
   * 检测内容类型
   */
  useEffect(() => {
    console.log('QuickCreateForm: useEffect - contentInput changed:', contentInput);

    if (!contentInput.trim()) {
      setDetectedType(null);
      return;
    }

    const type = detectContentType(contentInput);
    console.log('QuickCreateForm: detected type:', type);
    setDetectedType(type);

    if (type === 'url') {
      if (conf.htmlConf) {
        conf.htmlConf.url = contentInput;
        conf.htmlConf.html = '';
      }
    } else if (type === 'html') {
      if (conf.htmlConf) {
        conf.htmlConf.html = contentInput;
        conf.htmlConf.url = '';
      }
    }
  }, [contentInput, conf]);

  /**
   * 校验tag重复
   */
  useEffect(() => {
    console.log('QuickCreateForm: useEffect - tag changed, checking duplicate:', tag);

    if (!tag.trim()) {
      return;
    }

    if (isTagExists(tag)) {
      console.log('QuickCreateForm: tag already exists:', tag);
      setErrors(prev => ({ ...prev, tag: t('QuickCreateForm.tagDuplicateError') }));
    } else {
      console.log('QuickCreateForm: tag is unique:', tag);
      setErrors(prev => {
        const newErrors = { ...prev };
        delete newErrors.tag;
        return newErrors;
      });
    }
  }, [tag, t]);

  /**
   * 验证必填项
   */
  const validateRequired = (): boolean => {
    console.log('QuickCreateForm: validateRequired called');

    const newErrors: Record<string, string> = {};

    // tag 不再是必填项，但如果为空则自动使用 windowId
    if (!conf.tag.trim()) {
      console.log('QuickCreateForm: tag is empty, using windowId as tag:', conf.windowId);
      conf.tag = conf.windowId;
    } else if (isTagExists(conf.tag)) {
      // 如果用户手动输入了 tag，仍然检查重复
      console.log('QuickCreateForm: tag already exists:', conf.tag);
      newErrors.tag = t('QuickCreateForm.tagDuplicateError');
    }

    // 验证内容
    const url = (conf.htmlConf?.url || '').trim();
    const html = (conf.htmlConf?.html || '').trim();
    if (!url && !html) {
      console.log('QuickCreateForm: content is empty');
      newErrors.content = t('QuickCreateForm.validationErrorContent');
    } else if (detectedType === 'invalid') {
      console.log('QuickCreateForm: content type is invalid');
      newErrors.content = t('QuickCreateForm.contentInvalid');
    }

    console.log('QuickCreateForm: validation errors:', newErrors);
    setErrors(newErrors);

    return Object.keys(newErrors).length === 0;
  };

  /**
   * 快速创建
   */
  const handleQuickCreate = () => {
    console.log('QuickCreateForm: handleQuickCreate called');

    if (!validateRequired()) {
      console.log('QuickCreateForm: validation failed');
      return;
    }

    console.log('QuickCreateForm: quick create success, conf:', {
      tag: conf.tag,
      url: conf.htmlConf?.url,
      html: conf.htmlConf?.html,
      foregroundText: conf.floatWindowConf?.foregroundText,
    });

    onQuickCreate(conf);
  };

  /**
   * 详细编辑 - 切换到编辑模式
   */
  const handleFullConfig = () => {
    console.log('QuickCreateForm: handleFullConfig called');

    if (!validateRequired()) {
      console.log('QuickCreateForm: validation failed');
      return;
    }

    console.log('QuickCreateForm: switching to detailed edit mode, windowId:', conf.windowId);

    // 调用详细编辑回调,让父组件切换到编辑模式
    onDetailedEdit(conf);
  };

  /**
   * 取消
   */
  const handleCancel = () => {
    console.log('QuickCreateForm: handleCancel called');
    onCancel();
  };

  return (
    <Box sx={{ p: 2, maxWidth: 800, mx: 'auto' }}>
      <Typography variant="h5" gutterBottom>
        {t('QuickCreateForm.title')}
      </Typography>

      <Stack spacing={3} sx={{ mt: 3 }}>
        {/* 窗口标识 - 根据 hideTag 决定是否显示 */}
        {!hideTag && (
          <TextField
            label={
              <Box component="span">
                {t('QuickCreateForm.tagLabel')}
                <Chip
                  label={t('QuickCreateForm.tagRequired')}
                  size="small"
                  color="error"
                  sx={{ ml: 1, height: 20 }}
                />
              </Box>
            }
            placeholder={t('QuickCreateForm.tagPlaceholder')}
            helperText={errors.tag || t('QuickCreateForm.tagHelper')}
            error={!!errors.tag}
            value={tag}
            onChange={(e) => conf.tag = e.target.value}
            fullWidth
            required
          />
        )}

        {/* 内容(URL 或 HTML) */}
        <Box>
          <TextField
            label={
              <Box component="span">
                {t('QuickCreateForm.contentLabel')}
                <Chip
                  label={t('QuickCreateForm.contentRequired')}
                  size="small"
                  color="error"
                  sx={{ ml: 1, height: 20 }}
                />
              </Box>
            }
            placeholder={t('QuickCreateForm.contentPlaceholder')}
            helperText={errors.content || t('QuickCreateForm.contentHelper')}
            error={!!errors.content}
            value={contentInput}
            onChange={(e) => setContentInput(e.target.value)}
            fullWidth
            required
            multiline
            rows={3}
          />

          {detectedType === 'url' && (
            <Alert severity="success" sx={{ mt: 1 }}>
              {t('QuickCreateForm.detectedAsUrl')}
            </Alert>
          )}

          {detectedType === 'html' && (
            <Alert severity="success" sx={{ mt: 1 }}>
              {t('QuickCreateForm.detectedAsHtml')}
            </Alert>
          )}

          {detectedType === 'invalid' && (
            <Alert severity="error" sx={{ mt: 1 }}>
              {t('QuickCreateForm.contentInvalid')}
            </Alert>
          )}
        </Box>

        {/* 前台服务提示文本 */}
        {!hideForegroundText && (
          <TextField
            label={
              <Box component="span">
                {t('QuickCreateForm.foregroundTextLabel')}
                <Chip
                  label={t('QuickCreateForm.foregroundTextRecommended')}
                  size="small"
                  color="warning"
                  sx={{ ml: 1, height: 20 }}
                />
              </Box>
            }
            placeholder={t('QuickCreateForm.foregroundTextPlaceholder')}
            helperText={t('QuickCreateForm.foregroundTextHelper')}
            value={foregroundText}
            onChange={(e) => {
              console.log('[QuickCreateForm] foregroundText changed:', e.target.value)
              if (conf.floatWindowConf) {
                conf.floatWindowConf.foregroundText = e.target.value;
              }
            }}
            fullWidth
            multiline
            rows={2}
          />
        )}

        {/* 更多可选配置 - 直接展示,不折叠 */}
        <Box sx={{ mt: 2 }}>
          <Typography variant="subtitle2" gutterBottom>
            {t('QuickCreateForm.moreOptionsExpanded')}
          </Typography>
          <Stack spacing={2} sx={{ mt: 2 }}>
            {/* 窗口说明 */}
            <TextField
              label={t('QuickCreateForm.descriptionLabel')}
              placeholder={t('QuickCreateForm.descriptionPlaceholder')}
              value={conf.description || ''}
              onChange={(e) => conf.description = e.target.value}
              fullWidth
              multiline
              rows={2}
            />

            {/* TODO: WebView JS 参数 - 后续添加 */}
          </Stack>
        </Box>

        {/* 按钮组 */}
        <Stack direction="row" spacing={2} justifyContent="space-between">
          <Button onClick={handleCancel} variant="outlined">
            {t('QuickCreateForm.cancel')}
          </Button>

          <Stack direction="row" spacing={2}>
            <Button onClick={handleQuickCreate} variant="contained">
              {t('QuickCreateForm.quickCreate')}
            </Button>

            <Button onClick={handleFullConfig} variant="outlined">
              {t('QuickCreateForm.detailedEdit')}
            </Button>
          </Stack>
        </Stack>
      </Stack>
    </Box>
  );
}
